$ErrorActionPreference = 'Stop'
$target = 'jcfyyxsuspukcmybyhjj'
if ((Get-Content -Raw supabase\.temp\project-ref).Trim() -cne $target) { throw 'Refusing: linked project is not staging' }
$raw = supabase projects api-keys --project-ref $target --reveal --output json 2>$null | Out-String
$keys = $raw | ConvertFrom-Json
$service = ($keys | ? name -eq service_role | select -First 1).api_key
$anon = ($keys | ? name -eq anon | select -First 1).api_key
$base = "https://$target.supabase.co"
$admin = @{apikey=$service; Authorization="Bearer $service"; 'Content-Type'='application/json'; Prefer='return=representation'}
$anonHeaders = @{apikey=$anon; 'Content-Type'='application/json'}
function Call($method,$url,$headers,$body=$null) { if ($null -ne $body) { Invoke-RestMethod -Method $method -Uri $url -Headers $headers -Body ($body|ConvertTo-Json -Depth 12) } else { Invoke-RestMethod -Method $method -Uri $url -Headers $headers } }
function Rpc($name,$body,$token) { try { [pscustomobject]@{ok=$true; data=(Call POST "$base/rest/v1/rpc/$name" @{apikey=$anon;Authorization="Bearer $token";'Content-Type'='application/json'} $body);error=$null} } catch { [pscustomobject]@{ok=$false;data=$null;error=$_.ErrorDetails.Message} } }
function SignedUrl($bucket,$path,$token,$expiresIn=60) { Call POST "$base/functions/v1/file-signed-url" @{apikey=$anon;Authorization="Bearer $token";'Content-Type'='application/json'} @{bucket=$bucket;path=$path;expiresIn=$expiresIn} }
$result = [ordered]@{}
function Mark($n,$v) { $script:result[$n]=[bool]$v }
$clientId=$dealId=$projectId=$taskId=$todoId=$path=$null
try {
  # Resolve the three synthetic identities from their staging profile employee
  # IDs. Their email addresses are intentionally not part of the contract.
  $p = Call GET "$base/rest/v1/profiles?employee_id=in.(TEST-MANAGER,TEST-EMPLOYEE,TEST-OUTSIDER)&select=id,full_name,employee_id" $admin
  $mgr=($p|? employee_id -eq 'TEST-MANAGER').id; $emp=($p|? employee_id -eq 'TEST-EMPLOYEE').id; $out=($p|? employee_id -eq 'TEST-OUTSIDER').id
  if (-not $mgr -or -not $emp -or -not $out) { throw 'Missing staging security-test profiles.' }
  $users=(Call GET "$base/auth/v1/admin/users?per_page=100" $admin).users
  $spec=@(
    @{kind='manager';id=$mgr;user=($users|? id -eq $mgr | select -First 1)},
    @{kind='employee';id=$emp;user=($users|? id -eq $emp | select -First 1)},
    @{kind='outsider';id=$out;user=($users|? id -eq $out | select -First 1)}
  )
  if (@($spec | ? { -not $_.user -or [string]::IsNullOrWhiteSpace($_.user.email) }).Count -gt 0) { throw 'Auth user/profile UUID mismatch in staging.' }
  $tokens=@{}
  foreach($s in $spec){$b=New-Object byte[] 24;[Security.Cryptography.RandomNumberGenerator]::Fill($b);$pw=([Convert]::ToBase64String($b)+'Aa9!');Call PUT "$base/auth/v1/admin/users/$($s.id)" $admin @{password=$pw;email_confirm=$true}|Out-Null;$tokens[$s.kind]=(Call POST "$base/auth/v1/token?grant_type=password" $anonHeaders @{email=$s.user.email;password=$pw}).access_token;Remove-Variable pw -ErrorAction SilentlyContinue}
  Mark authenticated_login ($tokens.Count -eq 3)
  $c=Call POST "$base/rest/v1/crm_clients" $admin @{name='SECURITY TEST CLIENT';email='security-test@hrsys-staging.invalid';company='HR.sys Security Staging';assigned_to=$mgr};$clientId=$c.id
  $d=Call POST "$base/rest/v1/crm_deals" $admin @{title='SECURITY TEST DEAL';client_id=$clientId;stage='LEAD';amount=5000;assigned_to=$mgr;created_by=$mgr;first_contact_date='2026-09-28';event_type='TEST';contact_method='EMAIL'};$dealId=$d.id
  $mp=@{project_name='SECURITY TEST PROJECT';project_type='EVENT';description='Temporary authenticated Project verification record';assigned_people=@($emp);project_manager_id=$mgr;project_category='Enterprise';project_tags=@('staging');client_name='SECURITY TEST CLIENT';budget_amount='5000';actual_cost='1000'}
  $x=Rpc create_project_secure @{p_project=$mp} $tokens['test.manager@hrsys-staging.invalid'];if(!$x.ok){throw "Manager project creation failed: $($x.error)"};$projectId=$x.data.id;Call PATCH "$base/rest/v1/projects?id=eq.$projectId" $admin @{client_id=$clientId;deal_id=$dealId}|Out-Null;Mark manager_project_create $true
  Mark manager_project_list ((Rpc list_accessible_projects_secure @{} $tokens['test.manager@hrsys-staging.invalid']).ok);$detail=Rpc get_project_detail_secure @{p_project_id=$projectId} $tokens['test.manager@hrsys-staging.invalid'];Mark manager_project_detail $detail.ok;Mark manager_client_deal_relationships ($detail.ok -and $detail.data.project.client_id -eq $clientId -and $detail.data.project.deal_id -eq $dealId)
  Mark manager_project_update ((Rpc update_project_secure @{p_project_id=$projectId;p_changes=@{description='Manager update'}} $tokens['test.manager@hrsys-staging.invalid']).ok);Mark manager_status_change ((Rpc change_project_status @{p_project_id=$projectId;p_status='ACTIVE'} $tokens['test.manager@hrsys-staging.invalid']).ok)
  $tm=Rpc assign_project_team @{p_project_id=$projectId;p_project_manager_id=$mgr;p_assignee_ids=@($emp)} $tokens['test.manager@hrsys-staging.invalid'];$tr=Rpc assign_project_team @{p_project_id=$projectId;p_project_manager_id=$mgr;p_assignee_ids=@()} $tokens['test.manager@hrsys-staging.invalid'];$ta=Rpc assign_project_team @{p_project_id=$projectId;p_project_manager_id=$mgr;p_assignee_ids=@($emp)} $tokens['test.manager@hrsys-staging.invalid'];Mark manager_team_operations ($tm.ok -and $tr.ok -and $ta.ok)
  $td=Rpc add_project_todo @{p_project_id=$projectId;p_title='SECURITY TEST TODO';p_assignee_ids=@($emp);p_due_at=((Get-Date).AddDays(1).ToUniversalTime().ToString('o'))} $tokens['test.manager@hrsys-staging.invalid'];$todoId=$td.data.id;Mark manager_todo_create $td.ok;Mark manager_todo_list ((Rpc list_project_todos_secure @{p_project_id=$projectId} $tokens['test.manager@hrsys-staging.invalid']).ok);Mark manager_activity ((Rpc create_project_update_secure @{p_project_id=$projectId;p_summary='SECURITY TEST UPDATE';p_update_type='UPDATE'} $tokens['test.manager@hrsys-staging.invalid']).ok);$uh=Rpc list_project_updates_secure @{p_project_id=$projectId} $tokens['test.manager@hrsys-staging.invalid'];Mark manager_activity_history ($uh.ok -and @($uh.data).Count -gt 0)
  $mfin=$detail.data.project;Mark manager_financial_redaction ($null -eq $mfin.budget_amount -and $null -eq $mfin.actual_cost)
  $ed=Rpc get_project_detail_secure @{p_project_id=$projectId} $tokens['test.employee@hrsys-staging.invalid'];Mark employee_detail $ed.ok;Mark employee_todo_visibility ((Rpc list_project_todos_secure @{p_project_id=$projectId} $tokens['test.employee@hrsys-staging.invalid']).ok);Mark employee_todo_complete ((Rpc set_project_todo_completed @{p_todo_id=$todoId;p_completed=$true} $tokens['test.employee@hrsys-staging.invalid']).ok);Mark employee_update_rejected (!((Rpc update_project_secure @{p_project_id=$projectId;p_changes=@{description='IDOR'}} $tokens['test.employee@hrsys-staging.invalid']).ok));Mark employee_status_rejected (!((Rpc change_project_status @{p_project_id=$projectId;p_status='COMPLETED'} $tokens['test.employee@hrsys-staging.invalid']).ok));Mark employee_team_rejected (!((Rpc assign_project_team @{p_project_id=$projectId;p_project_manager_id=$emp;p_assignee_ids=@($emp)} $tokens['test.employee@hrsys-staging.invalid']).ok));$ef=$ed.data.project;Mark employee_financial_redaction ($null -eq $ef.budget_amount -and $null -eq $ef.actual_cost)
  $tc=Rpc create_task_secure @{p_payload=@{title='SECURITY TEST LINKED TASK';description='Temporary task';project_id=$projectId;assignee_ids=@($emp);priority='medium';category='General';visibility='public'}} $tokens['test.manager@hrsys-staging.invalid'];$taskId=$tc.data.id;Mark linked_task_create $tc.ok;Mark linked_task_employee_visibility ((Rpc get_task_secure @{p_task_id=$taskId} $tokens['test.employee@hrsys-staging.invalid']).ok)
  $path="$taskId/$mgr/security-test.txt";$bytes=[Text.Encoding]::UTF8.GetBytes('synthetic staging attachment');Call POST "$base/storage/v1/object/task-attachments/$path" @{apikey=$service;Authorization="Bearer $service";'Content-Type'='text/plain';'x-upsert'='true'} $bytes|Out-Null;Call POST "$base/rest/v1/task_attachments" $admin @{task_id=$taskId;user_id=$mgr;file_url="storage://task-attachments/$path";file_name='security-test.txt';file_type='text/plain';file_size=$bytes.Length;attachment_scope='TASK';visible_to_project_assignee=$true}|Out-Null;Mark employee_attachment_access ((Rpc list_task_attachments_secure @{p_task_id=$taskId;p_scope='TASK'} $tokens['test.employee@hrsys-staging.invalid']).ok);$ed2=Rpc get_project_detail_secure @{p_project_id=$projectId} $tokens['test.employee@hrsys-staging.invalid'];Mark employee_project_attachment_visibility ($ed2.ok -and @($ed2.data.attachments).Count -gt 0);$outsiderSignedRejected=$false;try{$signedResponse=SignedUrl 'task-attachments' $path $tokens['test.outsider@hrsys-staging.invalid'];$signedUrl=$signedResponse.signedUrl;if($signedUrl){try{Invoke-RestMethod -Method Get -Uri $signedUrl -ErrorAction Stop|Out-Null}catch{$outsiderSignedRejected=$true}}else{$outsiderSignedRejected=$true}}catch{$outsiderSignedRejected=$true};Mark outsider_signed_url_rejected $outsiderSignedRejected
  $ol=Rpc list_accessible_projects_secure @{} $tokens['test.outsider@hrsys-staging.invalid'];Mark outsider_project_list_rejected (!$ol.ok -or $null -eq $ol.data -or @($ol.data).Count -eq 0);$od=Rpc get_project_detail_secure @{p_project_id=$projectId} $tokens['test.outsider@hrsys-staging.invalid'];Mark outsider_project_idor_rejected (!$od.ok -or $null -eq $od.data -or @($od.data).Count -eq 0);$ot=Rpc list_project_todos_secure @{p_project_id=$projectId} $tokens['test.outsider@hrsys-staging.invalid'];Mark outsider_todo_idor_rejected (!$ot.ok -or $null -eq $ot.data -or @($ot.data).Count -eq 0);$oh=Rpc list_project_updates_secure @{p_project_id=$projectId} $tokens['test.outsider@hrsys-staging.invalid'];Mark outsider_activity_rejected (!$oh.ok -or $null -eq $oh.data -or @($oh.data).Count -eq 0);$og=Rpc get_task_secure @{p_task_id=$taskId} $tokens['test.outsider@hrsys-staging.invalid'];Mark outsider_task_idor_rejected (!$og.ok -or $null -eq $og.data -or @($og.data).Count -eq 0);Mark outsider_project_update_rejected (!((Rpc update_project_secure @{p_project_id=$projectId;p_changes=@{description='IDOR'}} $tokens['test.outsider@hrsys-staging.invalid']).ok));Mark outsider_status_rejected (!((Rpc change_project_status @{p_project_id=$projectId;p_status='COMPLETED'} $tokens['test.outsider@hrsys-staging.invalid']).ok));Mark outsider_team_rejected (!((Rpc assign_project_team @{p_project_id=$projectId;p_project_manager_id=$out;p_assignee_ids=@($out)} $tokens['test.outsider@hrsys-staging.invalid']).ok));Mark outsider_delete_rejected (!((Rpc delete_project_secure @{p_project_id=$projectId} $tokens['test.outsider@hrsys-staging.invalid']).ok))
  try{$drData=Call GET "$base/rest/v1/projects?id=eq.$projectId&select=id" @{apikey=$anon;Authorization="Bearer $($tokens['test.outsider@hrsys-staging.invalid'])";'Content-Type'='application/json'} $null;$dr=($null -eq $drData -or @($drData).Count -eq 0)}catch{$dr=$true};Mark outsider_direct_read_rejected $dr;try{Call POST "$base/rest/v1/projects" @{apikey=$anon;Authorization="Bearer $($tokens['test.outsider@hrsys-staging.invalid'])";'Content-Type'='application/json'} @{project_name='IDOR';project_type='EVENT'}|Out-Null;$di=$false}catch{$di=$true};Mark outsider_direct_insert_rejected $di;try{$du=Call PATCH "$base/rest/v1/projects?id=eq.$projectId" @{apikey=$anon;Authorization="Bearer $($tokens['test.outsider@hrsys-staging.invalid'])";'Content-Type'='application/json';Prefer='return=representation'} @{description='IDOR'};$directUpdate=(@($du).Count -eq 0)}catch{$directUpdate=$true};Mark outsider_direct_update_rejected $directUpdate;try{$dd=Call DELETE "$base/rest/v1/projects?id=eq.$projectId" @{apikey=$anon;Authorization="Bearer $($tokens['test.outsider@hrsys-staging.invalid'])";'Content-Type'='application/json';Prefer='return=representation'} $null;$directDelete=(@($dd).Count -eq 0)}catch{$directDelete=$true};Mark outsider_direct_delete_rejected $directDelete
  Mark manager_delete ((Rpc delete_project_secure @{p_project_id=$projectId} $tokens['test.manager@hrsys-staging.invalid']).ok)
} finally {
  if($path){try{Call DELETE "$base/storage/v1/object/task-attachments/$path" $admin $null|Out-Null}catch{}}
  if($taskId){try{Call DELETE "$base/rest/v1/task_attachments?task_id=eq.$taskId" $admin $null|Out-Null}catch{};try{Call DELETE "$base/rest/v1/tasks?id=eq.$taskId" $admin $null|Out-Null}catch{}}
  if($dealId){try{Call DELETE "$base/rest/v1/crm_deals?id=eq.$dealId" $admin $null|Out-Null}catch{}}
  if($clientId){try{Call DELETE "$base/rest/v1/crm_clients?id=eq.$clientId" $admin $null|Out-Null}catch{}}
}
$left=(supabase db query --linked "select (select count(*) from public.projects where project_name='SECURITY TEST PROJECT') as projects,(select count(*) from public.crm_clients where name='SECURITY TEST CLIENT') as clients,(select count(*) from public.crm_deals where title='SECURITY TEST DEAL') as deals,(select count(*) from public.tasks where title='SECURITY TEST LINKED TASK') as tasks;" 2>$null|Out-String);Mark cleanup_verified ($left -match '"projects"\s*:\s*0' -and $left -match '"clients"\s*:\s*0' -and $left -match '"deals"\s*:\s*0' -and $left -match '"tasks"\s*:\s*0')
$result.GetEnumerator()|%{"$($_.Key)=$($_.Value)"}
